sys_ws_operation.operation_script:
(function process(request, response) {
    var gr = new GlideRecord('cxs_ui_action_config');
    gr.initialize();
    gr.setValue('search_ui_config', '6eeed8f6dbbaa3402a4a9cb8db96190f');
    gr.setValue('search_resource', 'com.snc.contextual_search.search_resource.KnowledgeSearchResource');
    gr.setValue('search_ui_action', 'd587f286872a0300692cbba826cb0b6a');
    gr.setValue('action_label', 'Link to Interaction');
    gr.setValue('action_value', 'Attach');
    gr.setValue('active', true);
    gr.setValue('show_on_new', true);
    gr.setValue('order', 150);
    gr.setValue('sys_scope', 'global');
    var sysId = gr.insert();
    return { sys_id: sysId };
})(request, response);
